//! `ssk.d/<identity>.conf` (generated from recorded deployments) and the single
//! `Include` line ssk adds to the top of `~/.ssh/config`. Nothing the user wrote is
//! ever modified; the Include is prepended and the rest is preserved byte for byte.

use std::fmt::Write as _;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use crate::fsx;
use crate::settings;
use crate::state::Deployment;

pub const HEADER: &str =
    "# Generated by ssk. Do not edit: this file is rewritten on every `ssk copy`.\n";

/// `~/.ssh` when the dir is under $HOME (dotfiles-friendly), else the absolute path.
pub fn display_dir(ssh_dir: &Path) -> String {
    display_dir_with(ssh_dir, settings::home_dir().as_deref())
}

pub fn display_dir_with(ssh_dir: &Path, home: Option<&Path>) -> String {
    if let Some(home) = home
        && let Ok(rest) = ssh_dir.strip_prefix(home)
    {
        return format!("~/{}", rest.display());
    }
    ssh_dir.display().to_string()
}

pub fn include_line(ssh_dir: &Path) -> String {
    format!("Include {}/ssk.d/*.conf", display_dir(ssh_dir))
}

pub fn has_include(ssh_dir: &Path) -> io::Result<bool> {
    let want = include_line(ssh_dir);
    match fs::read_to_string(ssh_dir.join("config")) {
        Ok(text) => Ok(text.lines().any(|l| l.trim() == want)),
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(false),
        Err(e) => Err(e),
    }
}

/// Put the Include line first in `config`. Returns true if the file was changed.
pub fn ensure_include(ssh_dir: &Path) -> io::Result<bool> {
    if has_include(ssh_dir)? {
        return Ok(false);
    }
    fsx::ensure_private_dir(ssh_dir)?;
    let path = ssh_dir.join("config");
    let existing = match fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) if e.kind() == io::ErrorKind::NotFound => String::new(),
        Err(e) => return Err(e),
    };
    let line = include_line(ssh_dir);
    let new = if existing.is_empty() {
        format!("{line}\n")
    } else {
        format!("{line}\n\n{existing}")
    };
    if path.is_symlink() {
        // A dotfiles symlink: write through it rather than replacing it with a plain file.
        fs::write(&path, new)?;
    } else {
        fsx::write_private(&path, new.as_bytes())?;
    }
    Ok(true)
}

pub fn render_conf(ssh_dir: &Path, identity: &str, deployments: &[Deployment]) -> String {
    render_conf_with(&display_dir(ssh_dir), identity, deployments)
}

pub fn render_conf_with(dir_display: &str, identity: &str, deployments: &[Deployment]) -> String {
    let mut s = String::from(HEADER);
    for d in deployments {
        s.push('\n');
        let _ = writeln!(s, "Host {}", d.alias);
        if d.alias != d.host {
            let _ = writeln!(s, "    HostName {}", d.host);
        }
        if let Some(u) = &d.user {
            let _ = writeln!(s, "    User {u}");
        }
        if d.port != 22 {
            let _ = writeln!(s, "    Port {}", d.port);
        }
        let _ = writeln!(s, "    IdentityFile {dir_display}/{identity}");
        let _ = writeln!(s, "    IdentitiesOnly yes");
    }
    s
}

/// One word ssh reads as a literal Host name: no whitespace, no pattern characters,
/// nothing that would start a comment or a quoted string.
pub fn validate_alias(alias: &str) -> anyhow::Result<()> {
    if alias.is_empty()
        || alias
            .chars()
            .any(|c| c.is_whitespace() || c.is_control() || "*?!,#\"".contains(c))
    {
        anyhow::bail!(
            "'{alias}' is not a usable Host alias: it must be one word without whitespace or any of * ? ! , # \""
        );
    }
    Ok(())
}

pub fn conf_path(ssh_dir: &Path, identity: &str) -> PathBuf {
    ssh_dir.join("ssk.d").join(format!("{identity}.conf"))
}

pub fn write_conf(
    ssh_dir: &Path,
    identity: &str,
    deployments: &[Deployment],
) -> io::Result<PathBuf> {
    fsx::ensure_private_dir(&ssh_dir.join("ssk.d"))?;
    let path = conf_path(ssh_dir, identity);
    fsx::write_private(
        &path,
        render_conf(ssh_dir, identity, deployments).as_bytes(),
    )?;
    Ok(path)
}

/// Delete `ssk.d/<identity>.conf`. `Ok(false)` when there was none.
pub fn remove_conf(ssh_dir: &Path, identity: &str) -> io::Result<bool> {
    match fs::remove_file(conf_path(ssh_dir, identity)) {
        Ok(()) => Ok(true),
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(false),
        Err(e) => Err(e),
    }
}

/// The conf mirrors the deployments: written when there are some, deleted when none.
pub fn sync_conf(
    ssh_dir: &Path,
    identity: &str,
    deployments: &[Deployment],
) -> io::Result<Option<PathBuf>> {
    if deployments.is_empty() {
        remove_conf(ssh_dir, identity)?;
        Ok(None)
    } else {
        write_conf(ssh_dir, identity, deployments).map(Some)
    }
}

/// Non-comment lines of the user's own `config` that name `<ssh_dir>/<name>` as a whole
/// word, with 1-based line numbers. ssk never edits that file; callers warn.
pub fn user_config_mentions(ssh_dir: &Path, name: &str) -> io::Result<Vec<(usize, String)>> {
    let text = match fs::read_to_string(ssh_dir.join("config")) {
        Ok(t) => t,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(e) => return Err(e),
    };
    let mut needles = vec![
        format!("{}/{name}", display_dir(ssh_dir)),
        format!("{}/{name}", ssh_dir.display()),
        format!("~/.ssh/{name}"),
    ];
    needles.dedup();
    Ok(text
        .lines()
        .enumerate()
        .filter(|(_, line)| {
            let l = line.trim();
            !l.starts_with('#') && needles.iter().any(|n| mentions(l, n))
        })
        .map(|(i, line)| (i + 1, line.to_string()))
        .collect())
}

/// `needle` followed by end of line, whitespace or a quote: `~/.ssh/work` but not
/// `~/.ssh/work2` or `~/.ssh/work.pub`.
fn mentions(line: &str, needle: &str) -> bool {
    line.match_indices(needle).any(|(i, _)| {
        line[i + needle.len()..]
            .chars()
            .next()
            .is_none_or(|c| c.is_whitespace() || c == '"')
    })
}

/// One `Host` line of the user's own ssh config: its patterns, and the file it is in.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct HostLine {
    pub file: PathBuf,
    pub patterns: Vec<String>,
}

impl HostLine {
    /// ssh's rule: some pattern matches `name` and no `!pattern` does.
    pub fn applies_to(&self, name: &str) -> bool {
        let mut hit = false;
        for p in &self.patterns {
            match p.strip_prefix('!') {
                Some(negated) => {
                    if glob_match(negated, name) {
                        return false;
                    }
                }
                None => hit |= glob_match(p, name),
            }
        }
        hit
    }
}

/// The `Host` lines of the user's own `config` and of the files it `Include`s (one level
/// down, ssk's own `ssk.d` left out), in order. `Match` blocks are not read.
pub fn user_host_lines(ssh_dir: &Path) -> io::Result<Vec<HostLine>> {
    let main = ssh_dir.join("config");
    let text = match fs::read_to_string(&main) {
        Ok(t) => t,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(e) => return Err(e),
    };
    let mut lines = host_lines_in(&main, &text);
    let sskd = ssh_dir.join("ssk.d");
    for (key, args) in directives(&text) {
        if !key.eq_ignore_ascii_case("include") {
            continue;
        }
        for file in args.iter().flat_map(|pat| include_files(ssh_dir, pat)) {
            if file.starts_with(&sskd) {
                continue;
            }
            if let Ok(t) = fs::read_to_string(&file) {
                lines.extend(host_lines_in(&file, &t));
            }
        }
    }
    Ok(lines)
}

fn host_lines_in(file: &Path, text: &str) -> Vec<HostLine> {
    directives(text)
        .into_iter()
        .filter(|(key, _)| key.eq_ignore_ascii_case("host"))
        .map(|(_, patterns)| HostLine {
            file: file.to_path_buf(),
            patterns,
        })
        .collect()
}

/// `(keyword, arguments)` of every non-comment line; `Key=value` reads like `Key value`.
fn directives(text: &str) -> Vec<(String, Vec<String>)> {
    text.lines()
        .filter_map(|line| {
            let l = line.trim();
            if l.is_empty() || l.starts_with('#') {
                return None;
            }
            let mut words = l
                .split(|c: char| c.is_whitespace() || c == '=')
                .filter(|w| !w.is_empty());
            let key = words.next()?.to_string();
            Some((key, words.map(String::from).collect()))
        })
        .collect()
}

/// The files one `Include` argument names: `~/` and relative paths resolve as ssh
/// resolves them, and a glob in the file name is expanded in sorted order.
fn include_files(ssh_dir: &Path, pat: &str) -> Vec<PathBuf> {
    let path = match pat.strip_prefix("~/") {
        Some(rest) => match settings::home_dir() {
            Some(home) => home.join(rest),
            None => return Vec::new(),
        },
        None => ssh_dir.join(pat),
    };
    let name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default()
        .to_string();
    if !name.contains(['*', '?']) {
        return vec![path];
    }
    let Some(parent) = path.parent() else {
        return Vec::new();
    };
    let mut found: Vec<PathBuf> = fs::read_dir(parent)
        .map(|entries| {
            entries
                .flatten()
                .map(|e| e.path())
                .filter(|p| {
                    p.file_name()
                        .and_then(|n| n.to_str())
                        .is_some_and(|n| glob_match(&name, n))
                })
                .collect()
        })
        .unwrap_or_default();
    found.sort();
    found
}

/// ssh's pattern match: `*` any run of characters, `?` exactly one, case-insensitive.
pub fn glob_match(pattern: &str, text: &str) -> bool {
    let p: Vec<char> = pattern.to_lowercase().chars().collect();
    let t: Vec<char> = text.to_lowercase().chars().collect();
    let (mut pi, mut ti) = (0, 0);
    let mut star: Option<(usize, usize)> = None;
    while ti < t.len() {
        if pi < p.len() && (p[pi] == '?' || p[pi] == t[ti]) {
            pi += 1;
            ti += 1;
        } else if pi < p.len() && p[pi] == '*' {
            star = Some((pi, ti));
            pi += 1;
        } else if let Some((sp, st)) = star {
            pi = sp + 1;
            ti = st + 1;
            star = Some((sp, st + 1));
        } else {
            return false;
        }
    }
    p[pi..].iter().all(|c| *c == '*')
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::path::Path;

    fn dep(host: &str, user: Option<&str>, port: u16, alias: &str) -> Deployment {
        Deployment {
            host: host.into(),
            user: user.map(String::from),
            port,
            alias: alias.into(),
            installed: "t".into(),
        }
    }

    #[test]
    fn display_dir_prefers_tilde_under_home() {
        assert_eq!(
            display_dir_with(Path::new("/home/j/.ssh"), Some(Path::new("/home/j"))),
            "~/.ssh"
        );
        assert_eq!(
            display_dir_with(Path::new("/srv/keys"), Some(Path::new("/home/j"))),
            "/srv/keys"
        );
        assert_eq!(display_dir_with(Path::new("/srv/keys"), None), "/srv/keys");
    }

    #[test]
    fn renders_blocks_exactly() {
        let deps = vec![
            dep("10.0.0.5", Some("deploy"), 2222, "prod1"),
            dep("git.example", None, 22, "git.example"),
        ];
        let got = render_conf_with("~/.ssh", "work", &deps);
        let want = [
            HEADER.trim_end(),
            "",
            "Host prod1",
            "    HostName 10.0.0.5",
            "    User deploy",
            "    Port 2222",
            "    IdentityFile ~/.ssh/work",
            "    IdentitiesOnly yes",
            "",
            "Host git.example",
            "    IdentityFile ~/.ssh/work",
            "    IdentitiesOnly yes",
            "",
        ]
        .join("\n");
        assert_eq!(got, want);
    }

    #[test]
    fn ensure_include_creates_prepends_and_is_idempotent() {
        let tmp = tempfile::tempdir().unwrap();
        let dir = tmp.path();
        assert!(ensure_include(dir).unwrap());
        let cfg = dir.join("config");
        assert_eq!(
            fs::read_to_string(&cfg).unwrap(),
            format!("{}\n", include_line(dir))
        );
        assert_eq!(crate::fsx::mode_of(&cfg).unwrap(), 0o600);
        assert!(has_include(dir).unwrap());
        assert!(!ensure_include(dir).unwrap());

        fs::write(&cfg, "Host *\n    ServerAliveInterval 30\n").unwrap();
        assert!(!has_include(dir).unwrap());
        assert!(ensure_include(dir).unwrap());
        assert_eq!(
            fs::read_to_string(&cfg).unwrap(),
            format!(
                "{}\n\nHost *\n    ServerAliveInterval 30\n",
                include_line(dir)
            )
        );
    }

    #[test]
    fn ensure_include_writes_through_a_symlinked_config() {
        let tmp = tempfile::tempdir().unwrap();
        let real = tmp.path().join("dotfiles-config");
        fs::write(&real, "Host x\n").unwrap();
        let dir = tmp.path().join("ssh");
        fs::create_dir(&dir).unwrap();
        std::os::unix::fs::symlink(&real, dir.join("config")).unwrap();
        assert!(ensure_include(&dir).unwrap());
        assert!(dir.join("config").is_symlink(), "symlink must survive");
        assert!(fs::read_to_string(&real).unwrap().starts_with("Include "));
    }

    #[test]
    fn write_conf_creates_sskd_and_file_with_private_modes() {
        let tmp = tempfile::tempdir().unwrap();
        let path = write_conf(tmp.path(), "work", &[dep("h", None, 22, "h")]).unwrap();
        assert_eq!(path, conf_path(tmp.path(), "work"));
        assert_eq!(
            crate::fsx::mode_of(&tmp.path().join("ssk.d")).unwrap(),
            0o700
        );
        assert_eq!(crate::fsx::mode_of(&path).unwrap(), 0o600);
        let text = fs::read_to_string(&path).unwrap();
        assert!(text.starts_with(HEADER));
        assert!(text.contains("Host h\n"));
        assert!(text.contains("IdentitiesOnly yes\n"));
    }

    #[test]
    fn sync_conf_writes_or_removes() {
        let tmp = tempfile::tempdir().unwrap();
        let d = tmp.path();
        let p = sync_conf(d, "work", &[dep("h", None, 22, "h")])
            .unwrap()
            .unwrap();
        assert!(p.is_file());
        assert_eq!(sync_conf(d, "work", &[]).unwrap(), None);
        assert!(!p.exists());
        assert!(!remove_conf(d, "work").unwrap(), "already gone");
        write_conf(d, "work", &[dep("h", None, 22, "h")]).unwrap();
        assert!(remove_conf(d, "work").unwrap());
    }

    #[test]
    fn user_config_mentions_finds_whole_path_words_only() {
        let tmp = tempfile::tempdir().unwrap();
        let d = tmp.path();
        assert!(
            user_config_mentions(d, "work").unwrap().is_empty(),
            "no config file"
        );
        let text = format!(
            "Host a\n    IdentityFile {dir}/work\nHost b\n    IdentityFile {dir}/work2\n# IdentityFile {dir}/work\nHost c\n    IdentityFile \"{dir}/work\"\n    IdentityFile ~/.ssh/work\n",
            dir = d.display()
        );
        fs::write(d.join("config"), text).unwrap();
        let got = user_config_mentions(d, "work").unwrap();
        let lines: Vec<usize> = got.iter().map(|(n, _)| *n).collect();
        assert_eq!(lines, vec![2, 7, 8], "{got:?}");
    }

    #[test]
    fn validate_rejects_patterns_and_spaces() {
        assert!(validate_alias("prod-1.box").is_ok());
        for bad in ["", "a b", "a*", "a?", "!a", "a,b", "#a", "a\"", "a\tb"] {
            assert!(validate_alias(bad).is_err(), "{bad:?}");
        }
    }

    #[test]
    fn glob_matches_like_ssh() {
        assert!(glob_match("*", "anything"));
        assert!(glob_match("*", ""));
        assert!(glob_match("*.example.test", "box.example.test"));
        assert!(!glob_match("*.example.test", "example.test"));
        assert!(glob_match("rack-node-?", "rack-node-7"));
        assert!(!glob_match("rack-node-?", "rack-node-10"));
        assert!(glob_match("MyBox", "mybox"));
        assert!(glob_match("a*b*c", "axxbyyc"));
        assert!(!glob_match("a*b*c", "axxbyy"));
        assert!(glob_match("", ""));
        assert!(!glob_match("", "a"));
        assert!(!glob_match("abc", "ab"));
    }

    #[test]
    fn host_line_applies_unless_negated() {
        let line = |pats: &[&str]| HostLine {
            file: PathBuf::from("config"),
            patterns: pats.iter().map(|s| s.to_string()).collect(),
        };
        assert!(line(&["mybox"]).applies_to("mybox"));
        assert!(!line(&["mybox"]).applies_to("gem"));
        assert!(line(&["a", "b"]).applies_to("b"));
        let domain = line(&["*.example.test", "!bad.example.test"]);
        assert!(domain.applies_to("ok.example.test"));
        assert!(!domain.applies_to("bad.example.test"));
        assert!(
            !line(&["!x"]).applies_to("y"),
            "a negation alone matches nothing"
        );
    }

    #[test]
    fn user_host_lines_read_config_and_one_level_of_includes_but_not_sskd() {
        let tmp = tempfile::tempdir().unwrap();
        let d = tmp.path();
        assert!(user_host_lines(d).unwrap().is_empty(), "no config file");
        fs::create_dir_all(d.join("config.d")).unwrap();
        fs::create_dir_all(d.join("ssk.d")).unwrap();
        fs::write(
            d.join("config.d/lan.conf"),
            "host mybox other\n    HostName 10.0.0.5\nInclude deeper.inc\n",
        )
        .unwrap();
        fs::write(d.join("config.d/deeper.inc"), "Host deep\n").unwrap();
        fs::write(d.join("config.d/notes.txt"), "Host ignored\n").unwrap();
        fs::write(d.join("ssk.d/work.conf"), "Host managed\n").unwrap();
        fs::write(
            d.join("config"),
            format!(
                "{}\n# Host commented\nHost=eq\nInclude config.d/*.conf ssk.d/*.conf missing.conf\nMatch host x\nHost *\n",
                include_line(d)
            ),
        )
        .unwrap();
        let lines = user_host_lines(d).unwrap();
        let pats: Vec<String> = lines.iter().map(|l| l.patterns.join(" ")).collect();
        assert_eq!(pats, ["eq", "*", "mybox other"]);
        assert_eq!(lines[0].file, d.join("config"));
        assert_eq!(lines[2].file, d.join("config.d/lan.conf"));
    }
}
